namespace CustomerManagement.Api.Models;

/// <summary>
/// Represents a product record stored in the database.
/// </summary>
public class Product
{
    /// <summary>The unique identifier generated by the database on insert.</summary>
    public int Id { get; set; }

    /// <summary>The product name.</summary>
    public string Name { get; set; } = string.Empty;

    /// <summary>An optional description of the product.</summary>
    public string? Description { get; set; }

    /// <summary>The product price. Must be greater than 0.</summary>
    public decimal Price { get; set; }
}
